using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public struct StatusEffect
{
    public string name;
    public int stacks;
}


[Serializable]
public class EntityData
{
    public string name;
    public int maxHealth;
    public int currentHealth;
    public int block;
    public bool isAlive;

    public Vector3 worldPosition;  // Assigned by PlayerPrefab / EnemyRender
    public bool isPlayer;          // True for player, false for enemy

    public virtual void Initialize(string name, int maxHealth)
    {
        this.name = name;
        this.maxHealth = maxHealth;
        currentHealth = maxHealth;
        block = 0;
        isAlive = true;
    }

    public virtual void TakeDamage(int amount)
    {
        int originalAttack = amount;
        int blocked = Mathf.Min(block, amount);
        int remaining = amount - block;

        block = Mathf.Max(0, block - amount);

        if (remaining > 0)
        {
            currentHealth = Mathf.Max(0, currentHealth - remaining);
            if (currentHealth == 0) isAlive = false;

            // Case: damage passes through block → "-(amount-block)"
            TooltipManager.SpawnTooltip(
                worldPosition,
                "-" + remaining,
                Color.red,
                isPlayer ? TooltipDirection.Down : TooltipDirection.Up
            );
        }
        else
        {
            // Case: full block → "-X BLOCKED"
            TooltipManager.SpawnTooltip(
                worldPosition,
                "-" + originalAttack + " BLOCKED",
                new Color(0.7f, 0.3f, 1f), // purple
                isPlayer ? TooltipDirection.Down : TooltipDirection.Up
            );
        }
        if (isPlayer)
        {
            // Shake when taking damage - subtle but noticeable
            float shakeDuration = 0.15f + (amount * 0.01f); // Short shake, slightly longer for more damage
            float shakeMagnitude = 0.1f + (amount * 0.02f); // Subtle shake, scales with damage
            CameraShake.Shake(shakeDuration, shakeMagnitude);
        }
    }

    public virtual void GainBlock(int amount)
    {
        block += amount;

        TooltipManager.SpawnTooltip(
            worldPosition,
            "+" + amount + " BLOCK",
            Color.cyan,
            isPlayer ? TooltipDirection.Down : TooltipDirection.Up
        );
    }

    public virtual void Heal(int amount)
    {
        if (!isAlive) return;

        int healed = Mathf.Min(maxHealth - currentHealth, amount);
        if (healed <= 0) return;

        currentHealth += healed;

        TooltipManager.SpawnTooltip(
            worldPosition,
            "+" + healed,
            Color.green,
            isPlayer ? TooltipDirection.Down : TooltipDirection.Up
        );
    }

    public virtual void ApplyStatus(string statusId, int value)
    {
        // Implement status logic here
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public struct StatusEffect
{
    public string name;
    public int stacks;
}


[Serializable]
public class EntityData
{
    public string name;
    public int maxHealth;
    public int currentHealth;
    public int block;
    public int blockAge; // Tracks how many enemy turns this block has persisted
    public bool isAlive;

    public Vector3 worldPosition;  // Assigned by PlayerPrefab / EnemyRender
    public bool isPlayer;          // True for player, false for enemy

    public virtual void Initialize(string name, int maxHealth)
    {
        this.name = name;
        this.maxHealth = maxHealth;
        currentHealth = maxHealth;
        block = 0;
        blockAge = 0;
        isAlive = true;
    }

    public virtual void TakeDamage(int amount)
    {
        int originalAttack = amount;
        int blocked = Mathf.Min(block, amount);
        int remaining = amount - block;

        block = Mathf.Max(0, block - amount);

        if (remaining > 0)
        {
            currentHealth = Mathf.Max(0, currentHealth - remaining);
            if (currentHealth == 0) isAlive = false;

            // Case: damage passes through block → "-(amount-block)"
            TooltipManager.SpawnTooltip(
                worldPosition,
                "-" + remaining,
                Color.red,
                isPlayer ? TooltipDirection.Down : TooltipDirection.Up
            );
        }
        else
        {
            // Case: full block → "-X BLOCKED"
            TooltipManager.SpawnTooltip(
                worldPosition,
                "-" + originalAttack + " BLOCKED",
                new Color(0.7f, 0.3f, 1f), // purple
                isPlayer ? TooltipDirection.Down : TooltipDirection.Up
            );
        }
        if (isPlayer)
        {
            // Shake when taking damage - subtle but noticeable
            float shakeDuration = 0.15f + (amount * 0.01f); // Short shake, slightly longer for more damage
            float shakeMagnitude = 0.1f + (amount * 0.02f); // Subtle shake, scales with damage
            CameraShake.Shake(shakeDuration, shakeMagnitude);
        }
    }

    public virtual void GainBlock(int amount)
    {
        block += amount;
        blockAge = 0; // Reset age when gaining new block

        TooltipManager.SpawnTooltip(
            worldPosition,
            "+" + amount + " BLOCK",
            Color.cyan,
            isPlayer ? TooltipDirection.Down : TooltipDirection.Up
        );
    }

    public virtual void Heal(int amount)
    {
        if (!isAlive) return;

        int healed = Mathf.Min(maxHealth - currentHealth, amount);
        if (healed <= 0) return;

        currentHealth += healed;

        TooltipManager.SpawnTooltip(
            worldPosition,
            "+" + healed,
            Color.green,
            isPlayer ? TooltipDirection.Down : TooltipDirection.Up
        );
    }

    public virtual void ApplyStatus(string statusId, int value)
    {
        // Implement status logic here
    }
}

using Entities.Enemies.Helpers;
using Entities.Enemies.Data;
using Entities.Players.Data;
using GameItems;

namespace Entities.Enemies.Manager
{
    using System.Collections.Generic;
    using UnityEngine;

    public class EnemyManager : MonoBehaviour
    {
        [Header("Data")]
        public List<EnemyData> enemies = new();

        [Header("Intent Icons")]
        [Tooltip("Optional: Global intent icon config. If set, all enemies without their own icons will use this.")]
        public IntentIconConfig globalIntentIcons;

        [Header("Rendering")]
        [Tooltip("Parent container where enemy GameObjects (SpriteRenderer + Animator) will be spawned in world space.")]
        public Transform uiContainer; // now a Transform, not a RectTransform
        [Tooltip("Prefab for the enemy health bar UI (must have EnemyHealth component).")]
        [SerializeField] private GameObject healthBarPrefab;

        [Header("Layout (Line-up)")]
        [Tooltip("Horizontal spacing between enemies in world units.")]
        [SerializeField] private float horizontalSpacing = 2f;
        [Tooltip("Fixed Y offset for the line-up (local to container).")]
        [SerializeField] private float yOffset;
        [Tooltip("Center the lineup around X=0. If false, lineup starts at X=0 and grows positive.")]
        [SerializeField] private bool centerAlign = true;
        [Tooltip("Automatically layout enemies after (re)building.")]
        [SerializeField] private bool autoLayoutOnBuild = true;

        [Header("Health Bar Settings")]
        [Tooltip("Local position offset for health bar relative to enemy.")]
        [SerializeField] private Vector3 healthBarOffset = new Vector3(0f, 0.17f, 0f);

        private readonly List<EnemyRender> _activeRenders = new();

        public void InitializeEnemies(List<EnemyData> enemyList)
        {
            enemies = enemyList;
            BuildEnemyUI();
        }

        private void BuildEnemyUI()
        {
            // Cleanup old
            foreach (var r in _activeRenders)
            {
                if (r != null) Destroy(r.gameObject);
            }
            _activeRenders.Clear();

            if (uiContainer == null)
            {
                Debug.LogWarning("EnemyManager: uiContainer not set. Enemies will not be rendered.");
                return;
            }

            if (healthBarPrefab == null)
            {
                Debug.LogWarning("EnemyManager: healthBarPrefab not set. Health bars will not be created.");
            }

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                var go = new GameObject(string.IsNullOrEmpty(enemy.enemyName) ? $"Enemy_{i}" : enemy.enemyName,
                    typeof(Animator), typeof(SpriteRenderer), typeof(EnemyRender));

                // Parent under the provided container
                var t = go.transform;
                t.SetParent(uiContainer, false);

                // World-space transform defaults
                t.localPosition = Vector3.zero;
                t.localScale = Vector3.one * 10f;
                t.localRotation = Quaternion.identity;

                var sr = go.GetComponent<SpriteRenderer>();
                sr.sprite = enemy.artwork;
                sr.sortingOrder = i; // order by spawn index (front-to-back or vice versa as needed)

                // Add health bar if prefab is available
                if (healthBarPrefab != null)
                {
                    var healthBarGo = Instantiate(healthBarPrefab, go.transform);
                    var healthComp = healthBarGo.GetComponent<EnemyHealth>();
                    if (healthComp != null)
                    {
                        healthComp.SetLocalPosition(healthBarOffset);
                        // Initial health will be set in EnemyRender.Bind
                    }
                    else
                    {
                        Debug.LogWarning($"EnemyManager: healthBarPrefab for {enemy.enemyName} does not have EnemyHealth component.");
                    }
                }

                var render = go.GetComponent<EnemyRender>();
                render.Bind(enemy);

                _activeRenders.Add(render);
            }

            if (autoLayoutOnBuild)
                ApplyLineUpLayout();
        }

        private void ApplyLineUpLayout()
        {
            int count = _activeRenders.Count;
            if (count == 0) return;

            float startX = centerAlign ? -((count - 1) * horizontalSpacing) * 0.5f : 0f;

            for (int i = 0; i < count; i++)
            {
                var r = _activeRenders[i];
                if (r == null) continue;

                var t = r.transform;
                t.localPosition = new Vector3(startX + i * horizontalSpacing, yOffset, 0f);
            }
        }

        // Roll/decide next intents for all alive enemies (called at round start)
        public void RollNextIntents()
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // DON'T reset block here - let it persist through the player's turn

                // Auto-assign global intent icons if enemy doesn't have its own
                if (enemy.intentIcons == null && globalIntentIcons != null)
                {
                    enemy.intentIcons = globalIntentIcons.ToMapping();
                }

                enemy.DecideNextIntent();

                // Ensure idle is playing so player sees them idling before attack
                var r = GetRenderFor(enemy);
                if (r != null)
                {
                    r.PlayIdle();
                    r.UpdateIntentIcon(); // Show the intent icon
                    r.UpdateHealth(); // Keep existing block visible
                }
            }
        }


        public void RemoveDeadEnemies()
        {
            for (int i = enemies.Count - 1; i >= 0; i--)
            {
                if (!enemies[i].isAlive)
                {
                    enemies.RemoveAt(i);

                    if (_activeRenders.Count > i)
                        _activeRenders.RemoveAt(i);
                }
            }

            // re-layout remaining enemies
            // ApplyLineUpLayout();
        }

        // Enemies execute their previously decided intents with delays (turn-based feel)
        public System.Collections.IEnumerator ExecuteEnemyTurnSequence(PlayerData player)
        {
            // Reset all enemies' block at the START of the enemy turn
            // (After the player has had their turn to attack shielded enemies)
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (enemy.isAlive)
                {
                    // enemy.block = 0;
                    var r = GetRenderFor(enemy);
                    if (r != null)
                    {
                        // r.UpdateHealth(); // Show shields disappearing
                    }
                }
            }

            // Small visual delay to show shields disappearing
            yield return new WaitForSeconds(0.3f);

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                Debug.Log($"[EnemyManager] {enemy.enemyName} is taking their turn...");

                // Get the render for animation
                var r = GetRenderFor(enemy);

                // Show move name popup BEFORE executing the move
                if (r != null)
                {
                    string moveName = r.GetMoveNameForIntent(enemy.currentIntent);

                    // Show popup and wait for it to be visible
                    r.ShowMoveNamePopup(moveName);
                    yield return new WaitForSeconds(0.3f); // Brief pause to let player see the move name
                }

                // Play intent animation based on type
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    if (r != null) r.PlayAttack();

                    // Wait for attack animation to play out
                    yield return new WaitForSeconds(0.5f);
                }
                else if (enemy.currentIntent == EnemyIntent.Block)
                {
                    if (r != null) r.PlayIdle(); // Or a defend animation if you have one
                    yield return new WaitForSeconds(0.3f);
                }
                else
                {
                    // Default for Heal/Buff/other intents
                    if (r != null) r.PlayIdle();
                    yield return new WaitForSeconds(0.3f);
                }

                // Execute the intent (apply damage, gain block, etc.)
                enemy.ExecuteIntent(player);

                // Update the enemy's health display to show new shield/health values
                if (r != null)
                {
                    r.UpdateHealth();
                }

                // Brief pause to show the effect
                yield return new WaitForSeconds(0.4f);

                // Return to idle after action
                if (r != null) r.PlayIdle();

                // Delay before next enemy acts
                yield return new WaitForSeconds(0.6f);
            }

            Debug.Log("[EnemyManager] All enemies have completed their turns.");
        }

        // Legacy synchronous method - kept for backwards compatibility but deprecated
        [System.Obsolete("Use ExecuteEnemyTurnSequence coroutine instead for turn-based delays")]
        public void ExecuteEnemyTurn(ref PlayerData player)
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // Play attack animation right before executing if intent is attack
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    var r = GetRenderFor(enemy);
                    if (r != null) r.PlayAttack();
                }

                enemy.ExecuteIntent(player);
            }
        }

        // Call after enemy takes damage to update health display
        public void UpdateEnemyHealth(EnemyData enemy)
        {
            var render = GetRenderFor(enemy);
            if (render != null)
            {
                render.UpdateHealth();

                // Play hurt animation if still alive
                if (enemy.isAlive)
                {
                    render.PlayHurt();
                }
                else
                {
                    render.PlayDeath();

                    RemoveDeadEnemies(); // remove from manager list
                }
            }
            FindFirstObjectByType<RoundManager>()?.CheckImmediateEndConditions();
        }

        // for the start of player rounds, reset all enemy block helper
        public void ResetAllEnemyBlock()
        {
            foreach (var enemy in enemies)
            {
                if (!enemy.isAlive) continue;

                enemy.block = 0;

                var r = GetRenderFor(enemy);
                if (r != null)
                    r.UpdateHealth();
            }
        }

        private EnemyRender GetRenderFor(EnemyData enemy)
        {
            // Renders are built in the same order as enemies
            int idx = enemies.IndexOf(enemy);
            if (idx >= 0 && idx < _activeRenders.Count)
                return _activeRenders[idx];
            return null;
        }

        public bool AllEnemiesDefeated()
        {
            foreach (var e in enemies)
                if (e.isAlive) return false;
            return true;
        }
    }
}

using Entities.Enemies.Helpers;
using Entities.Enemies.Data;
using Entities.Players.Data;
using GameItems;

namespace Entities.Enemies.Manager
{
    using System.Collections.Generic;
    using UnityEngine;

    public class EnemyManager : MonoBehaviour
    {
        [Header("Data")]
        public List<EnemyData> enemies = new();

        [Header("Intent Icons")]
        [Tooltip("Optional: Global intent icon config. If set, all enemies without their own icons will use this.")]
        public IntentIconConfig globalIntentIcons;

        [Header("Rendering")]
        [Tooltip("Parent container where enemy GameObjects (SpriteRenderer + Animator) will be spawned in world space.")]
        public Transform uiContainer; // now a Transform, not a RectTransform
        [Tooltip("Prefab for the enemy health bar UI (must have EnemyHealth component).")]
        [SerializeField] private GameObject healthBarPrefab;

        [Header("Layout (Line-up)")]
        [Tooltip("Horizontal spacing between enemies in world units.")]
        [SerializeField] private float horizontalSpacing = 2f;
        [Tooltip("Fixed Y offset for the line-up (local to container).")]
        [SerializeField] private float yOffset;
        [Tooltip("Center the lineup around X=0. If false, lineup starts at X=0 and grows positive.")]
        [SerializeField] private bool centerAlign = true;
        [Tooltip("Automatically layout enemies after (re)building.")]
        [SerializeField] private bool autoLayoutOnBuild = true;

        [Header("Health Bar Settings")]
        [Tooltip("Local position offset for health bar relative to enemy.")]
        [SerializeField] private Vector3 healthBarOffset = new Vector3(0f, 0.17f, 0f);

        private readonly List<EnemyRender> _activeRenders = new();

        public void InitializeEnemies(List<EnemyData> enemyList)
        {
            enemies = enemyList;
            BuildEnemyUI();
        }

        private void BuildEnemyUI()
        {
            // Cleanup old
            foreach (var r in _activeRenders)
            {
                if (r != null) Destroy(r.gameObject);
            }
            _activeRenders.Clear();

            if (uiContainer == null)
            {
                Debug.LogWarning("EnemyManager: uiContainer not set. Enemies will not be rendered.");
                return;
            }

            if (healthBarPrefab == null)
            {
                Debug.LogWarning("EnemyManager: healthBarPrefab not set. Health bars will not be created.");
            }

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                var go = new GameObject(string.IsNullOrEmpty(enemy.enemyName) ? $"Enemy_{i}" : enemy.enemyName,
                    typeof(Animator), typeof(SpriteRenderer), typeof(EnemyRender));

                // Parent under the provided container
                var t = go.transform;
                t.SetParent(uiContainer, false);

                // World-space transform defaults
                t.localPosition = Vector3.zero;
                t.localScale = Vector3.one * 10f;
                t.localRotation = Quaternion.identity;

                var sr = go.GetComponent<SpriteRenderer>();
                sr.sprite = enemy.artwork;
                sr.sortingOrder = i; // order by spawn index (front-to-back or vice versa as needed)

                // Add health bar if prefab is available
                if (healthBarPrefab != null)
                {
                    var healthBarGo = Instantiate(healthBarPrefab, go.transform);
                    var healthComp = healthBarGo.GetComponent<EnemyHealth>();
                    if (healthComp != null)
                    {
                        healthComp.SetLocalPosition(healthBarOffset);
                        // Initial health will be set in EnemyRender.Bind
                    }
                    else
                    {
                        Debug.LogWarning($"EnemyManager: healthBarPrefab for {enemy.enemyName} does not have EnemyHealth component.");
                    }
                }

                var render = go.GetComponent<EnemyRender>();
                render.Bind(enemy);

                _activeRenders.Add(render);
            }

            if (autoLayoutOnBuild)
                ApplyLineUpLayout();
        }

        private void ApplyLineUpLayout()
        {
            int count = _activeRenders.Count;
            if (count == 0) return;

            float startX = centerAlign ? -((count - 1) * horizontalSpacing) * 0.5f : 0f;

            for (int i = 0; i < count; i++)
            {
                var r = _activeRenders[i];
                if (r == null) continue;

                var t = r.transform;
                t.localPosition = new Vector3(startX + i * horizontalSpacing, yOffset, 0f);
            }
        }

        // Roll/decide next intents for all alive enemies (called at round start)
        public void RollNextIntents()
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // DON'T reset block here - let it persist through the player's turn

                // Auto-assign global intent icons if enemy doesn't have its own
                if (enemy.intentIcons == null && globalIntentIcons != null)
                {
                    enemy.intentIcons = globalIntentIcons.ToMapping();
                }

                enemy.DecideNextIntent();

                // Ensure idle is playing so player sees them idling before attack
                var r = GetRenderFor(enemy);
                if (r != null)
                {
                    r.PlayIdle();
                    r.UpdateIntentIcon(); // Show the intent icon
                    r.UpdateHealth(); // Keep existing block visible
                }
            }
        }


        public void RemoveDeadEnemies()
        {
            for (int i = enemies.Count - 1; i >= 0; i--)
            {
                if (!enemies[i].isAlive)
                {
                    enemies.RemoveAt(i);

                    if (_activeRenders.Count > i)
                        _activeRenders.RemoveAt(i);
                }
            }

            // re-layout remaining enemies
            // ApplyLineUpLayout();
        }

        // Enemies execute their previously decided intents with delays (turn-based feel)
        public System.Collections.IEnumerator ExecuteEnemyTurnSequence(PlayerData player)
        {

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                Debug.Log($"[EnemyManager] {enemy.enemyName} is taking their turn...");

                // Get the render for animation
                var r = GetRenderFor(enemy);

                // Show move name popup BEFORE executing the move
                if (r != null)
                {
                    string moveName = r.GetMoveNameForIntent(enemy.currentIntent);

                    // Show popup and wait for it to be visible
                    r.ShowMoveNamePopup(moveName);
                    yield return new WaitForSeconds(0.3f); // Brief pause to let player see the move name
                }

                // Play intent animation based on type
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    if (r != null) r.PlayAttack();

                    // Wait for attack animation to play out
                    yield return new WaitForSeconds(0.5f);
                }
                else if (enemy.currentIntent == EnemyIntent.Block)
                {
                    if (r != null) r.PlayIdle(); // Or a defend animation if you have one
                    yield return new WaitForSeconds(0.3f);
                }
                else
                {
                    // Default for Heal/Buff/other intents
                    if (r != null) r.PlayIdle();
                    yield return new WaitForSeconds(0.3f);
                }

                // Execute the intent (apply damage, gain block, etc.)
                enemy.ExecuteIntent(player);

                // Update the enemy's health display to show new shield/health values
                if (r != null)
                {
                    r.UpdateHealth();
                }

                // Brief pause to show the effect
                yield return new WaitForSeconds(0.4f);

                // Return to idle after action
                if (r != null) r.PlayIdle();

                // Delay before next enemy acts
                yield return new WaitForSeconds(0.6f);
            }

            Debug.Log("[EnemyManager] All enemies have completed their turns.");
        }

        // Legacy synchronous method - kept for backwards compatibility but deprecated
        [System.Obsolete("Use ExecuteEnemyTurnSequence coroutine instead for turn-based delays")]
        public void ExecuteEnemyTurn(ref PlayerData player)
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // Play attack animation right before executing if intent is attack
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    var r = GetRenderFor(enemy);
                    if (r != null) r.PlayAttack();
                }

                enemy.ExecuteIntent(player);
            }
        }

        // Call after enemy takes damage to update health display
        public void UpdateEnemyHealth(EnemyData enemy)
        {
            var render = GetRenderFor(enemy);
            if (render != null)
            {
                render.UpdateHealth();

                // Play hurt animation if still alive
                if (enemy.isAlive)
                {
                    render.PlayHurt();
                }
                else
                {
                    render.PlayDeath();

                    RemoveDeadEnemies(); // remove from manager list
                }
            }
            FindFirstObjectByType<RoundManager>()?.CheckImmediateEndConditions();
        }

        // Age enemy block and reset old block (1+ turns old)
        // This allows block gained THIS turn to persist through the next round
        public void ResetAllEnemyBlock()
        {
            foreach (var enemy in enemies)
            {
                if (!enemy.isAlive) continue;

                // Increment block age
                if (enemy.block > 0)
                {
                    enemy.blockAge++;

                    // Only reset block that's 1 or more turns old
                    if (enemy.blockAge >= 2)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block expired (age {enemy.blockAge}): {enemy.block} → 0");
                        enemy.block = 0;
                        enemy.blockAge = 0;

                        var r = GetRenderFor(enemy);
                        if (r != null)
                            r.UpdateHealth();
                    }
                    else
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block persists (age {enemy.blockAge}): {enemy.block} block");
                    }
                }
            }
        }

        private EnemyRender GetRenderFor(EnemyData enemy)
        {
            // Renders are built in the same order as enemies
            int idx = enemies.IndexOf(enemy);
            if (idx >= 0 && idx < _activeRenders.Count)
                return _activeRenders[idx];
            return null;
        }

        public bool AllEnemiesDefeated()
        {
            foreach (var e in enemies)
                if (e.isAlive) return false;
            return true;
        }
    }
}

using UnityEngine;
using System.Collections;
using Entities.Enemies.Manager;

public class RoundManager : MonoBehaviour
{
    [Header("Managers")] public PlayerManager player;
    public EnemyManager enemyManager;

    [Header("State")] public int roundNumber = 1;
    public bool playerTurn = true;
    public bool battleActive = false;

    // Prevents checking end conditions during wave transitions
    private bool _isTransitioningWaves = false;

    [Header("End Screen UI")] 
    public ScreenFadeUI endScreenUI;

    [Header("Round Transition UI")]
    [Tooltip("Optional: UI for showing round transitions (e.g., 'ROUND 1'). Can be the same as endScreenUI.")]
    public ScreenFadeUI roundTransitionUI;

    [Header("Timer Settings")] [Tooltip("Time in seconds for each player turn")]
    public float turnTimeLimit = 15f;

    [Tooltip("Current remaining time in the turn")]
    public float currentTurnTime;

    private bool timerActive = false;

    [Header("UI")] [Tooltip("Optional: Deck viewer that shows the current hand.")]
    public GameItems.DeckViewer handViewer;

    [Tooltip("Optional: Deck viewer that shows the draw pile.")]
    public GameItems.DeckViewer drawPileViewer;

    [Tooltip("Optional: Deck viewer that shows the discard pile.")]
    public GameItems.DeckViewer discardPileViewer;

    // -------------------------------------------------------
    // Wave System
    // -------------------------------------------------------
    [System.NonSerialized]
    public System.Action onWaveComplete; // Callback when all enemies in current wave are defeated

    // -------------------------------------------------------
    // Public method to trigger victory (called by BattleManager)
    // -------------------------------------------------------
    public void TriggerVictory()
    {
        if (!battleActive) return;
        battleActive = false;
        _isTransitioningWaves = false; // Clear flag
        HandlePlayerWin();
    }

    // -------------------------------------------------------
    // Initialization
    // -------------------------------------------------------
    public void Initialize(PlayerManager playerManager, EnemyManager enemyMgr)
    {
        player = playerManager;
        enemyManager = enemyMgr;
    }

    // -------------------------------------------------------
    // Update - Handle turn timer
    // -------------------------------------------------------
    private void Update()
    {
        CheckImmediateEndConditions();
        if (!battleActive || !playerTurn || !timerActive) return;

        // Countdown timer
        currentTurnTime -= Time.deltaTime;

        // Check if timer expired
        if (currentTurnTime <= 0f)
        {
            Debug.Log("⏰ Turn timer expired! Ending player turn.");
            currentTurnTime = 0f;
            timerActive = false;
            EndPlayerTurn();
            return;
        }

        // Check if player has run out of energy (optional auto-end)
        if (player != null && player.playerData != null && player.playerData.currentEnergy <= 0)
        {
            Debug.Log("⚡ Player energy depleted! Ending turn early.");
            timerActive = false;
            EndPlayerTurn();
            return;
        }
    }

    // -------------------------------------------------------
    // Start first round
    // -------------------------------------------------------
    public void StartRound()
    {
        if (player == null || enemyManager == null)
        {
            Debug.LogError("RoundManager: Missing managers!");
            return;
        }

        roundNumber = 1;
        playerTurn = true;
        battleActive = true;

        Debug.Log($"--- Round {roundNumber} Start ---");

        // Show round transition UI
        StartCoroutine(StartRoundWithTransition());
    }

    private IEnumerator StartRoundWithTransition()
    {
        // Show "ROUND 1" transition
        if (roundTransitionUI != null)
        {
            yield return StartCoroutine(roundTransitionUI.ShowRoundTransition(roundNumber, isNewWave: false));
        }

        // Enemies roll their next intents so the player can see them before acting
        enemyManager.RollNextIntents();
        player.StartTurn();

        RefreshDeckViewers();

        // Start turn timer
        StartTurnTimer();
    }

    // -------------------------------------------------------
    // Start a new wave (called by BattleManager)
    // -------------------------------------------------------
    public void StartNewWave()
    {
        if (player == null || enemyManager == null)
        {
            Debug.LogError("RoundManager: Missing managers!");
            return;
        }

        // Clear transition flag - we're ready to check end conditions again
        _isTransitioningWaves = false;

        // Don't reset round number - continue incrementing through waves
        playerTurn = true;
        battleActive = true;

        Debug.Log($"--- New Wave - Round {roundNumber} Start ---");

        // Show wave transition UI
        StartCoroutine(StartWaveWithTransition());
    }

    private IEnumerator StartWaveWithTransition()
    {
        // Show "WAVE X" transition
        if (roundTransitionUI != null)
        {
            yield return StartCoroutine(roundTransitionUI.ShowRoundTransition(roundNumber, isNewWave: true));
        }

        // Enemies roll their next intents so the player can see them before acting
        enemyManager.RollNextIntents();
        player.StartTurn();

        RefreshDeckViewers();

        // Start turn timer
        StartTurnTimer();
    }

    // -------------------------------------------------------
    // Called when player ends their turn
    // -------------------------------------------------------
    public void EndPlayerTurn()
    {
        if (!battleActive || !playerTurn) return;

        // Stop timer
        timerActive = false;

        Debug.Log("Player turn ended.");

        // Animate cards discarding BEFORE clearing data
        if (handViewer != null && handViewer.GetRenders().Count > 0)
        {
            handViewer.ClearSmooth(onComplete: () =>
            {
                // After animation completes, clear the data and continue
                player.EndTurn();
                // Refresh other viewers but not hand (already cleared with animation)
                RefreshDeckViewers(skipHand: true);
                playerTurn = false;
                StartCoroutine(EnemyPhase());
            });
        }
        else
        {
            // No cards to animate, proceed normally
            player.EndTurn();
            RefreshDeckViewers();
            playerTurn = false;
            StartCoroutine(EnemyPhase());
        }
    }

    // -------------------------------------------------------
    // Enemy turn phase coroutine
    // -------------------------------------------------------
    private IEnumerator EnemyPhase()
    {
        Debug.Log("Enemy turn begins...");

        yield return new WaitForSeconds(.5f);

        // Reset block is now handled inside ExecuteEnemyTurnSequence
        // enemyManager.ResetAllEnemyBlock();

        // Enemies execute their actions with delayed sequence
        yield return StartCoroutine(enemyManager.ExecuteEnemyTurnSequence(player.playerData));

        yield return new WaitForSeconds(.5f);

        if (player.playerData.isAlive && !enemyManager.AllEnemiesDefeated())
        {
            NextRound();
        }
        else
        {
            EndBattle();
        }
    }

    // -------------------------------------------------------
    // Begin the next round
    // -------------------------------------------------------
    private void NextRound()
    {
        roundNumber++;
        playerTurn = true;

        Debug.Log($"--- Round {roundNumber} Start ---");

        // Show round transition UI before starting the round
        StartCoroutine(NextRoundWithTransition());
    }

    private IEnumerator NextRoundWithTransition()
    {
        // Show "ROUND X" transition
        if (roundTransitionUI != null)
        {
            yield return StartCoroutine(roundTransitionUI.ShowRoundTransition(roundNumber, isNewWave: false));
        }

        // Roll intents for the upcoming enemy turn so the player can plan accordingly
        enemyManager.RollNextIntents();
        player.StartTurn();

        RefreshDeckViewers();

        // Restart turn timer
        StartTurnTimer();
    }

    // -------------------------------------------------------
    // Start/Restart the turn timer
    // -------------------------------------------------------
    private void StartTurnTimer()
    {
        currentTurnTime = turnTimeLimit;
        timerActive = true;
        Debug.Log($"⏱️ Turn timer started: {turnTimeLimit} seconds");
    }

    // -------------------------------------------------------
    // End battle (victory or defeat)
    // -------------------------------------------------------
    private void EndBattle()
    {
        // Prevent double calls
        if (!battleActive) return;
        battleActive = false;

        // Redirect to immediate end logic
        CheckImmediateEndConditions();
    }

    private void RefreshDeckViewers(bool skipHand = false)
    {
        if (handViewer != null && !skipHand)
        {
            handViewer.SetPlayer(player);
            handViewer.SetSource(GameItems.DeckViewer.Source.Hand, rebuild: true);
        }

        if (drawPileViewer != null)
        {
            drawPileViewer.SetPlayer(player);
            drawPileViewer.SetSource(GameItems.DeckViewer.Source.DrawPile, rebuild: true);
        }

        if (discardPileViewer != null)
        {
            discardPileViewer.SetPlayer(player);
            discardPileViewer.SetSource(GameItems.DeckViewer.Source.DiscardPile, rebuild: true);
        }
    }

    // -------------------------------------------------------
    // Checks if battle should end RIGHT NOW (not end of round)
    // Call this whenever player/enemy health changes
    // -------------------------------------------------------
    public void CheckImmediateEndConditions()
    {
        if (!battleActive) return;

        // Don't check end conditions during wave transitions
        if (_isTransitioningWaves) return;

        // Player dead
        if (player.playerData.currentHealth <= 0)
        {
            Debug.Log(" Player died — immediate game over.");
            battleActive = false;
            HandlePlayerLose();
            return;
        }

        // All enemies dead - could be wave complete or battle complete
        if (enemyManager.AllEnemiesDefeated())
        {
            Debug.Log(" All enemies defeated in current wave!");

            // Set transition flag to prevent repeated calls
            _isTransitioningWaves = true;

            // Notify BattleManager that wave is complete
            // BattleManager will decide if there are more waves or if battle is won
            if (onWaveComplete != null)
            {
                onWaveComplete.Invoke();
            }
            else
            {
                // Fallback: if no wave system, just win immediately
                battleActive = false;
                HandlePlayerWin();
            }
            return;
        }
    }

    // -------------------------------------------------------
    // PLAYER WINS
    // -------------------------------------------------------
    private void HandlePlayerWin()
    {
        Debug.Log(" Player Victory!");

        // Fade screen + show text
        if (endScreenUI != null)
            endScreenUI.ShowMessage("YOU WIN", new Color(1f, 0.84f, 0.0f)); // gold

        // TODO: update timer shit
        var clock = FindObjectOfType<ClockTimer>();
        if (clock != null)
            clock.AddTime(10f); // TODO: adjust reward amount
        StartCoroutine(ReturnToOverworldDelayed());
    }

    // -------------------------------------------------------
    // PLAYER LOSSES
    // -------------------------------------------------------
    private void HandlePlayerLose()
    {
        Debug.Log("❌ Player Defeat!");

        if (endScreenUI != null)
            endScreenUI.ShowMessage("YOU LOSE", Color.red);

        // TODO: wrong todo just ummm timer change flag shit
        var clock = FindObjectOfType<ClockTimer>();
        if (clock != null)
            clock.RemoveTime(100f); // TODO: adjust penalty amount
        StartCoroutine(ReturnToOverworldDelayed());
    }

    private IEnumerator ReturnToOverworldDelayed()
    {
        yield return new WaitForSeconds(3f);

        UnityEngine.SceneManagement.SceneManager.LoadScene("Overworld");
    }
}

using UnityEngine;
using System.Collections;
using Entities.Enemies.Manager;

public class RoundManager : MonoBehaviour
{
    [Header("Managers")] public PlayerManager player;
    public EnemyManager enemyManager;

    [Header("State")] public int roundNumber = 1;
    public bool playerTurn = true;
    public bool battleActive = false;

    // Prevents checking end conditions during wave transitions
    private bool _isTransitioningWaves = false;

    [Header("End Screen UI")] 
    public ScreenFadeUI endScreenUI;

    [Header("Round Transition UI")]
    [Tooltip("Optional: UI for showing round transitions (e.g., 'ROUND 1'). Can be the same as endScreenUI.")]
    public ScreenFadeUI roundTransitionUI;

    [Header("Timer Settings")] [Tooltip("Time in seconds for each player turn")]
    public float turnTimeLimit = 15f;

    [Tooltip("Current remaining time in the turn")]
    public float currentTurnTime;

    private bool timerActive = false;

    [Header("UI")] [Tooltip("Optional: Deck viewer that shows the current hand.")]
    public GameItems.DeckViewer handViewer;

    [Tooltip("Optional: Deck viewer that shows the draw pile.")]
    public GameItems.DeckViewer drawPileViewer;

    [Tooltip("Optional: Deck viewer that shows the discard pile.")]
    public GameItems.DeckViewer discardPileViewer;

    // -------------------------------------------------------
    // Wave System
    // -------------------------------------------------------
    [System.NonSerialized]
    public System.Action onWaveComplete; // Callback when all enemies in current wave are defeated

    // -------------------------------------------------------
    // Public method to trigger victory (called by BattleManager)
    // -------------------------------------------------------
    public void TriggerVictory()
    {
        if (!battleActive) return;
        battleActive = false;
        _isTransitioningWaves = false; // Clear flag
        HandlePlayerWin();
    }

    // -------------------------------------------------------
    // Initialization
    // -------------------------------------------------------
    public void Initialize(PlayerManager playerManager, EnemyManager enemyMgr)
    {
        player = playerManager;
        enemyManager = enemyMgr;
    }

    // -------------------------------------------------------
    // Update - Handle turn timer
    // -------------------------------------------------------
    private void Update()
    {
        CheckImmediateEndConditions();
        if (!battleActive || !playerTurn || !timerActive) return;

        // Countdown timer
        currentTurnTime -= Time.deltaTime;

        // Check if timer expired
        if (currentTurnTime <= 0f)
        {
            Debug.Log("⏰ Turn timer expired! Ending player turn.");
            currentTurnTime = 0f;
            timerActive = false;
            EndPlayerTurn();
            return;
        }

        // Check if player has run out of energy (optional auto-end)
        if (player != null && player.playerData != null && player.playerData.currentEnergy <= 0)
        {
            Debug.Log("⚡ Player energy depleted! Ending turn early.");
            timerActive = false;
            EndPlayerTurn();
            return;
        }
    }

    // -------------------------------------------------------
    // Start first round
    // -------------------------------------------------------
    public void StartRound()
    {
        if (player == null || enemyManager == null)
        {
            Debug.LogError("RoundManager: Missing managers!");
            return;
        }

        roundNumber = 1;
        playerTurn = true;
        battleActive = true;

        Debug.Log($"--- Round {roundNumber} Start ---");

        // Show round transition UI
        StartCoroutine(StartRoundWithTransition());
    }

    private IEnumerator StartRoundWithTransition()
    {
        // Show "ROUND 1" transition
        if (roundTransitionUI != null)
        {
            yield return StartCoroutine(roundTransitionUI.ShowRoundTransition(roundNumber, isNewWave: false));
        }

        // Enemies roll their next intents so the player can see them before acting
        enemyManager.RollNextIntents();
        player.StartTurn();

        RefreshDeckViewers();

        // Start turn timer
        StartTurnTimer();
    }

    // -------------------------------------------------------
    // Start a new wave (called by BattleManager)
    // -------------------------------------------------------
    public void StartNewWave()
    {
        if (player == null || enemyManager == null)
        {
            Debug.LogError("RoundManager: Missing managers!");
            return;
        }

        // Clear transition flag - we're ready to check end conditions again
        _isTransitioningWaves = false;

        // Don't reset round number - continue incrementing through waves
        playerTurn = true;
        battleActive = true;

        Debug.Log($"--- New Wave - Round {roundNumber} Start ---");

        // Show wave transition UI
        StartCoroutine(StartWaveWithTransition());
    }

    private IEnumerator StartWaveWithTransition()
    {
        // Show "WAVE X" transition
        if (roundTransitionUI != null)
        {
            yield return StartCoroutine(roundTransitionUI.ShowRoundTransition(roundNumber, isNewWave: true));
        }

        // DON'T reset enemy block here - new wave enemies start with 0 block anyway

        // Enemies roll their next intents so the player can see them before acting
        enemyManager.RollNextIntents();
        player.StartTurn();

        RefreshDeckViewers();

        // Start turn timer
        StartTurnTimer();
    }

    // -------------------------------------------------------
    // Called when player ends their turn
    // -------------------------------------------------------
    public void EndPlayerTurn()
    {
        if (!battleActive || !playerTurn) return;

        // Stop timer
        timerActive = false;

        Debug.Log("Player turn ended.");

        // Animate cards discarding BEFORE clearing data
        if (handViewer != null && handViewer.GetRenders().Count > 0)
        {
            handViewer.ClearSmooth(onComplete: () =>
            {
                // After animation completes, clear the data and continue
                player.EndTurn();
                // Refresh other viewers but not hand (already cleared with animation)
                RefreshDeckViewers(skipHand: true);
                playerTurn = false;
                StartCoroutine(EnemyPhase());
            });
        }
        else
        {
            // No cards to animate, proceed normally
            player.EndTurn();
            RefreshDeckViewers();
            playerTurn = false;
            StartCoroutine(EnemyPhase());
        }
    }

    // -------------------------------------------------------
    // Enemy turn phase coroutine
    // -------------------------------------------------------
    private IEnumerator EnemyPhase()
    {
        Debug.Log("Enemy turn begins...");

        yield return new WaitForSeconds(.5f);

        // Enemies execute their actions with delayed sequence
        yield return StartCoroutine(enemyManager.ExecuteEnemyTurnSequence(player.playerData));

        yield return new WaitForSeconds(.5f);

        // Reset enemy block AFTER their turn completes
        // This means block gained this turn will protect through the NEXT full round
        if (enemyManager != null)
        {
            enemyManager.ResetAllEnemyBlock();
            Debug.Log("Enemy block reset after enemy turn completes");
        }

        if (player.playerData.isAlive && !enemyManager.AllEnemiesDefeated())
        {
            NextRound();
        }
        else
        {
            EndBattle();
        }
    }

    // -------------------------------------------------------
    // Begin the next round
    // -------------------------------------------------------
    private void NextRound()
    {
        roundNumber++;
        playerTurn = true;

        Debug.Log($"--- Round {roundNumber} Start ---");

        // Show round transition UI before starting the round
        StartCoroutine(NextRoundWithTransition());
    }

    private IEnumerator NextRoundWithTransition()
    {
        // Show "ROUND X" transition
        if (roundTransitionUI != null)
        {
            yield return StartCoroutine(roundTransitionUI.ShowRoundTransition(roundNumber, isNewWave: false));
        }

        // DON'T reset enemy block here - let it persist through this round
        // Block will be reset AFTER the enemy turn executes

        // Roll intents for the upcoming enemy turn so the player can plan accordingly
        enemyManager.RollNextIntents();
        player.StartTurn();

        RefreshDeckViewers();

        // Restart turn timer
        StartTurnTimer();
    }

    // -------------------------------------------------------
    // Start/Restart the turn timer
    // -------------------------------------------------------
    private void StartTurnTimer()
    {
        currentTurnTime = turnTimeLimit;
        timerActive = true;
        Debug.Log($"⏱️ Turn timer started: {turnTimeLimit} seconds");
    }

    // -------------------------------------------------------
    // End battle (victory or defeat)
    // -------------------------------------------------------
    private void EndBattle()
    {
        // Prevent double calls
        if (!battleActive) return;
        battleActive = false;

        // Redirect to immediate end logic
        CheckImmediateEndConditions();
    }

    private void RefreshDeckViewers(bool skipHand = false)
    {
        if (handViewer != null && !skipHand)
        {
            handViewer.SetPlayer(player);
            handViewer.SetSource(GameItems.DeckViewer.Source.Hand, rebuild: true);
        }

        if (drawPileViewer != null)
        {
            drawPileViewer.SetPlayer(player);
            drawPileViewer.SetSource(GameItems.DeckViewer.Source.DrawPile, rebuild: true);
        }

        if (discardPileViewer != null)
        {
            discardPileViewer.SetPlayer(player);
            discardPileViewer.SetSource(GameItems.DeckViewer.Source.DiscardPile, rebuild: true);
        }
    }

    // -------------------------------------------------------
    // Checks if battle should end RIGHT NOW (not end of round)
    // Call this whenever player/enemy health changes
    // -------------------------------------------------------
    public void CheckImmediateEndConditions()
    {
        if (!battleActive) return;

        // Don't check end conditions during wave transitions
        if (_isTransitioningWaves) return;

        // Player dead
        if (player.playerData.currentHealth <= 0)
        {
            Debug.Log(" Player died — immediate game over.");
            battleActive = false;
            HandlePlayerLose();
            return;
        }

        // All enemies dead - could be wave complete or battle complete
        if (enemyManager.AllEnemiesDefeated())
        {
            Debug.Log(" All enemies defeated in current wave!");

            // Set transition flag to prevent repeated calls
            _isTransitioningWaves = true;

            // Notify BattleManager that wave is complete
            // BattleManager will decide if there are more waves or if battle is won
            if (onWaveComplete != null)
            {
                onWaveComplete.Invoke();
            }
            else
            {
                // Fallback: if no wave system, just win immediately
                battleActive = false;
                HandlePlayerWin();
            }
            return;
        }
    }

    // -------------------------------------------------------
    // PLAYER WINS
    // -------------------------------------------------------
    private void HandlePlayerWin()
    {
        Debug.Log(" Player Victory!");

        // Fade screen + show text
        if (endScreenUI != null)
            endScreenUI.ShowMessage("YOU WIN", new Color(1f, 0.84f, 0.0f)); // gold

        // TODO: update timer shit
        var clock = FindObjectOfType<ClockTimer>();
        if (clock != null)
            clock.AddTime(10f); // TODO: adjust reward amount
        StartCoroutine(ReturnToOverworldDelayed());
    }

    // -------------------------------------------------------
    // PLAYER LOSSES
    // -------------------------------------------------------
    private void HandlePlayerLose()
    {
        Debug.Log("❌ Player Defeat!");

        if (endScreenUI != null)
            endScreenUI.ShowMessage("YOU LOSE", Color.red);

        // TODO: wrong todo just ummm timer change flag shit
        var clock = FindObjectOfType<ClockTimer>();
        if (clock != null)
            clock.RemoveTime(100f); // TODO: adjust penalty amount
        StartCoroutine(ReturnToOverworldDelayed());
    }

    private IEnumerator ReturnToOverworldDelayed()
    {
        yield return new WaitForSeconds(3f);

        UnityEngine.SceneManagement.SceneManager.LoadScene("Overworld");
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace GameItems
{
    /// <summary>
    /// Displays the turn timer UI with a countdown and optional visual feedback.
    /// </summary>
    public class TurnTimerUI : MonoBehaviour
    {
        [Header("References")]
        [Tooltip("Reference to the RoundManager to read timer values")]
        public RoundManager roundManager;

        [Header("UI Elements")]
        [Tooltip("Text component to display the remaining time")]
        public TextMeshProUGUI timerText;

        [Tooltip("Optional fill image to show timer visually")]
        public Image timerFillImage;

        [Header("Visual Settings")]
        [Tooltip("Color when time is plentiful")]
        public Color normalColor = Color.white;

        [Tooltip("Color when time is running low")]
        public Color warningColor = Color.yellow;

        [Tooltip("Color when time is almost out")]
        public Color criticalColor = Color.red;

        [Tooltip("Time threshold for warning color (seconds)")]
        public float warningThreshold = 7f;

        [Tooltip("Time threshold for critical color (seconds)")]
        public float criticalThreshold = 3f;

        private void Start()
        {
            // Auto-find RoundManager if not assigned
            if (roundManager == null)
            {
                roundManager = FindFirstObjectByType<RoundManager>();
            }

            if (roundManager == null)
            {
                Debug.LogError("TurnTimerUI: RoundManager not found!");
                enabled = false;
            }
        }

        private void Update()
        {
            if (roundManager == null || !roundManager.playerTurn || !roundManager.battleActive)
            {
                // Hide timer when not player's turn
                if (timerText != null) timerText.text = "";
                if (timerFillImage != null) timerFillImage.fillAmount = 0f;
                return;
            }

            float timeRemaining = roundManager.currentTurnTime;
            float timeLimit = roundManager.turnTimeLimit;

            // Update text
            if (timerText != null)
            {
                timerText.text = $"{Mathf.CeilToInt(timeRemaining)}s";

                // Update color based on time remaining
                if (timeRemaining <= criticalThreshold)
                {
                    timerText.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerText.color = warningColor;
                }
                else
                {
                    timerText.color = normalColor;
                }
            }

            // Update fill image
            if (timerFillImage != null && timeLimit > 0)
            {
                timerFillImage.fillAmount = timeRemaining / timeLimit;

                // Update fill color
                if (timeRemaining <= criticalThreshold)
                {
                    timerFillImage.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerFillImage.color = warningColor;
                }
                else
                {
                    timerFillImage.color = normalColor;
                }
            }
        }
    }
}
